mapper.select:
SELECT m.document_revision,m.body_sha256,m.created_by,m.created_at,m.based_on_document_revision, CASE WHEN r.document_id=m.document_id AND r.snapshot_id=m.snapshot_id AND r.body_sha256=m.body_sha256 AND m.content_sha256=m.body_sha256 AND v.owner_project_id=m.project_id AND v.entity_kind='DOCUMENT_REVISION' THEN v.content_sha256 ELSE NULL END AS content_sha256 FROM document_revision_meta m LEFT JOIN document_revision r ON r.tenant_id=m.tenant_id AND r.project_id=m.project_id AND r.document_revision=m.document_revision LEFT JOIN version_registry v ON v.tenant_id=m.tenant_id AND v.version_id=m.document_revision WHERE m.project_id=#{projectId} AND m.document_id=#{documentId}
AND (m.created_at < #{afterCreatedAt} OR (m.created_at=#{afterCreatedAt} AND m.document_revision < #{afterDocumentRevision}))
AND 1=0
ORDER BY m.created_at DESC,m.document_revision DESC LIMIT #{limit}

SELECT r.review_id FROM review_decision r
JOIN document_revision_meta m ON m.tenant_id=r.tenant_id AND m.project_id=r.project_id AND m.document_revision=r.document_revision
WHERE r.project_id=#{projectId} AND m.document_id=#{documentId} AND r.document_revision=#{documentRevision}
ORDER BY r.review_id LIMIT #{limit}
